package awssdkv2_test

import (
	"testing"

	"github.com/moderneinc/recipes-go/recipes/migration/awssdkv2"
	"github.com/openrewrite/rewrite/rewrite-go/pkg/test"
)

const pathStyleHelpers = `
	// Code generated by MigrateAwsSdkGoToV2. DO NOT EDIT.

	package main

	import "github.com/aws/aws-sdk-go-v2/service/s3"

	// awsCompatS3PathStyle stands in for aws-sdk-go v1's S3ForcePathStyle, which a
	// config applied to every S3 client built from it.
	func awsCompatS3PathStyle(force bool) func(string, any) {
		return func(_ string, options any) {
			if o, ok := options.(*s3.Options); ok {
				o.UsePathStyle = force
			}
		}
	}
`

// v1 held path-style addressing on the session's config, for every S3 client
// built from it; v2's config carries service options each client applies, so
// the setting reaches S3's clients the same way.
func TestMigrateSessionPathStyle(t *testing.T) {
	test.NewRecipeSpec().WithRecipe(&awssdkv2.MigrateAwsSdkGoToV2{}).RewriteRun(t,
		test.Golang(`
			package main

			import (
				"github.com/aws/aws-sdk-go/aws"
				"github.com/aws/aws-sdk-go/aws/session"
			)

			func load(minio bool) (*session.Session, error) {
				return session.NewSession(&aws.Config{
					Region:           aws.String("us-east-1"),
					S3ForcePathStyle: aws.Bool(minio),
				})
			}
		`, `
			package main

			import (
				"context"

				"github.com/aws/aws-sdk-go-v2/aws"
				"github.com/aws/aws-sdk-go-v2/config"
			)

			func load(minio bool) (aws.Config, error) {
				return config.LoadDefaultConfig(context.TODO(), config.WithRegion("us-east-1"), config.WithServiceOptions(awsCompatS3PathStyle(minio)))
			}
		`),
		test.Generated("zz_awssdkv2_s3.go", pathStyleHelpers),
	)
}

// A client's own config literal carries it as a service option too, merged over
// the session's as v1 merged it; a config the file keeps gains it on a write.
func TestMigrateClientAndKeptConfigPathStyle(t *testing.T) {
	test.NewRecipeSpec().WithRecipe(&awssdkv2.MigrateAwsSdkGoToV2{}).RewriteRun(t,
		test.Golang(`
			package main

			import (
				"github.com/aws/aws-sdk-go/aws"
				"github.com/aws/aws-sdk-go/aws/session"
				"github.com/aws/aws-sdk-go/service/s3"
			)

			func client(sess *session.Session) *s3.S3 {
				return s3.New(sess, &aws.Config{S3ForcePathStyle: aws.Bool(true)})
			}

			func load(minio bool) (*session.Session, error) {
				cfg := &aws.Config{}
				if minio {
					cfg.S3ForcePathStyle = aws.Bool(true)
				}
				return session.NewSession(cfg)
			}
		`, `
			package main

			import (
				"context"

				"github.com/aws/aws-sdk-go-v2/aws"
				"github.com/aws/aws-sdk-go-v2/config"
				"github.com/aws/aws-sdk-go-v2/service/s3"
			)

			func client(sess aws.Config) *s3.Client {
				return s3.NewFromConfig(awsCompatMergeConfig(sess, &aws.Config{ServiceOptions: []func(string, any){awsCompatS3PathStyle(true)}}))
			}

			func load(minio bool) (aws.Config, error) {
				cfg := &aws.Config{}
				if minio {
					cfg.ServiceOptions = append(cfg.ServiceOptions, awsCompatS3PathStyle(true))
				}
				return config.LoadDefaultConfig(context.TODO(), awsCompatConfigOptions(cfg)...)
			}
		`),
		test.Generated("zz_awssdkv2_s3.go", pathStyleHelpers),
		test.Generated("zz_awssdkv2_config.go", configHelpersIn("main")),
	)
}

// v2 holds the setting on each S3 client, with nothing on the config to read.
func TestMigrateBlockedByPathStyleRead(t *testing.T) {
	test.NewRecipeSpec().WithRecipe(&awssdkv2.MigrateAwsSdkGoToV2{}).RewriteRun(t,
		test.Golang(`
			package main

			import (
				"github.com/aws/aws-sdk-go/aws"
				"github.com/aws/aws-sdk-go/aws/session"
			)

			func load() (*session.Session, bool) {
				cfg := &aws.Config{S3ForcePathStyle: aws.Bool(true)}
				sess, _ := session.NewSession(cfg)
				return sess, *cfg.S3ForcePathStyle
			}
		`),
	)
}
